/* /workspace/spec/model.c
 *
 * Independent black-box model of the tsl::hopscotch_map arithmetic exercised by
 * /workspace/dataset/test11.cpp:
 *
 *     tsl::hopscotch_map<int,int> map;                 // bucket_count()==0, size()==0
 *     for (i=0;i<count;i++) map.insert({i, i*9});      // all keys distinct
 *     cout << map.load_factor() << " ";
 *     map.max_load_factor(0.5);
 *     map.rehash(0);
 *     cout << map.load_factor() << endl;
 *
 * Model under test (float == IEEE binary32 everywhere the library uses `float`):
 *   DEFAULT_MLF          = 0.9f
 *   threshold(bc, mlf)   = (size_t)((float)bc * mlf)          // truncating cast
 *   insert of a NEW key  : if (size >= threshold) { bc = (bc==0 ? 2 : bc*2); recompute } ; size++
 *   load_factor()        = bc==0 ? 0.0f : (float)size / (float)bc
 *   max_load_factor(x)   : mlf = (float)x ; recompute threshold
 *   rehash(0)            : n = (size_t)ceilf((float)size / mlf);   // std::max(0, ...) == n
 *                          bc = (n==0 ? 0 : round_up_pow2(n))
 *   printing             : ostream<<float  ==  printf("%g", (double)f)
 *
 * usage:
 *   model N                 -> prints "%g %g\n"
 *   model --slow N          -> same, but literal per-insert loop
 *   model --batch           -> reads counts (one per line) on stdin, prints "N\t<out>"
 *   model --selfcheck LO HI -> fast closed form vs literal loop over [LO,HI]
 *   model --thrtable        -> bucket_count -> threshold table for both mlf values
 *   model --shrink LO HI    -> report any count where rehash(0) reduces bucket_count
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stddef.h>
#include <stdint.h>

typedef uint64_t u64;

#define DEFAULT_MLF 0.9f
#define REHASH_MLF  0.5f

static u64 round_up_pow2(u64 v) {
    if (v == 0) return 0;
    u64 p = 1;
    while (p < v) p <<= 1;
    return p;
}

/* (size_t)((float)bc * mlf) : float multiply, then truncate toward zero */
static u64 threshold_of(u64 bc, float mlf) {
    float prod = (float)bc * mlf;
    return (u64)prod;
}

static float load_factor_of(u64 size, u64 bc) {
    if (bc == 0) return 0.0f;
    return (float)size / (float)bc;
}

/* literal simulation: one iteration per inserted element */
static u64 bc_slow(u64 count) {
    u64 bc = 0, size = 0, thr = threshold_of(0, DEFAULT_MLF);
    for (u64 i = 0; i < count; i++) {
        if (size >= thr) {
            bc = (bc == 0) ? 2 : bc * 2;
            thr = threshold_of(bc, DEFAULT_MLF);
        }
        size++;
    }
    return bc;
}

/* closed form: jump straight to each growth trigger */
static u64 bc_fast(u64 count) {
    if (count == 0) return 0;
    u64 bc = 0, thr = threshold_of(0, DEFAULT_MLF);
    for (;;) {
        /* size is currently min(count, thr) unless a grow is due at size==thr */
        bc = (bc == 0) ? 2 : bc * 2;
        thr = threshold_of(bc, DEFAULT_MLF);
        if (count <= thr) return bc;
        /* size reaches thr, the next insert triggers another grow */
    }
}

/* rehash(0) with mlf: returns the resulting bucket_count */
static u64 rehash_zero(u64 size, float mlf) {
    float want_f = ceilf((float)size / mlf);
    u64 want = (u64)want_f;
    return round_up_pow2(want);
}

static void emit(u64 count, int slow, int with_prefix) {
    u64 size = count;
    u64 bc = slow ? bc_slow(count) : bc_fast(count);

    float lf1 = load_factor_of(size, bc);

    float mlf = REHASH_MLF;              /* map.max_load_factor(0.5) */
    (void)threshold_of(bc, mlf);         /* threshold recomputed, unobservable here */

    bc = rehash_zero(size, mlf);         /* map.rehash(0) */
    (void)threshold_of(bc, mlf);

    float lf2 = load_factor_of(size, bc);

    if (with_prefix) printf("%llu\t", (unsigned long long)count);
    printf("%g %g\n", (double)lf1, (double)lf2);
}

int main(int argc, char **argv) {
    if (argc >= 2 && strcmp(argv[1], "--batch") == 0) {
        char line[128];
        while (fgets(line, sizeof line, stdin)) {
            if (line[0] == '\n' || line[0] == '\0') continue;
            u64 n = strtoull(line, NULL, 10);
            emit(n, 0, 1);
        }
        return 0;
    }
    if (argc >= 4 && strcmp(argv[1], "--selfcheck") == 0) {
        u64 lo = strtoull(argv[2], NULL, 10), hi = strtoull(argv[3], NULL, 10), bad = 0;
        for (u64 n = lo; n <= hi; n++) {
            u64 a = bc_slow(n), b = bc_fast(n);
            if (a != b) { bad++; printf("SELFCHECK n=%llu slow=%llu fast=%llu\n",
                                       (unsigned long long)n,(unsigned long long)a,(unsigned long long)b); }
        }
        printf("selfcheck [%llu,%llu] mismatches=%llu\n",
               (unsigned long long)lo,(unsigned long long)hi,(unsigned long long)bad);
        return bad != 0;
    }
    if (argc >= 2 && strcmp(argv[1], "--thrtable") == 0) {
        printf("k\tbucket_count\tthr_mlf0.9\tthr_mlf0.5\texact_0.9_product\n");
        printf("0\t0\t%llu\t%llu\t0\n", (unsigned long long)threshold_of(0,0.9f),
                                        (unsigned long long)threshold_of(0,0.5f));
        for (int k = 1; k <= 24; k++) {
            u64 bc = (u64)1 << k;
            printf("%d\t%llu\t%llu\t%llu\t%.10f\n", k, (unsigned long long)bc,
                   (unsigned long long)threshold_of(bc, 0.9f),
                   (unsigned long long)threshold_of(bc, 0.5f),
                   (double)((float)bc * 0.9f));
        }
        return 0;
    }
    if (argc >= 4 && strcmp(argv[1], "--shrink") == 0) {
        u64 lo = strtoull(argv[2], NULL, 10), hi = strtoull(argv[3], NULL, 10), n_shrink = 0, n_same = 0, n_grow = 0;
        for (u64 n = lo; n <= hi; n++) {
            u64 before = bc_fast(n), after = rehash_zero(n, 0.5f);
            if (after < before) { if (n_shrink < 20) printf("SHRINK count=%llu %llu -> %llu\n",
                (unsigned long long)n,(unsigned long long)before,(unsigned long long)after); n_shrink++; }
            else if (after == before) n_same++; else n_grow++;
        }
        printf("[%llu,%llu] shrink=%llu same=%llu grow=%llu\n",
               (unsigned long long)lo,(unsigned long long)hi,
               (unsigned long long)n_shrink,(unsigned long long)n_same,(unsigned long long)n_grow);
        return 0;
    }
    if (argc >= 3 && strcmp(argv[1], "--slow") == 0) { emit(strtoull(argv[2],NULL,10), 1, 0); return 0; }
    if (argc < 2) { fprintf(stderr, "usage: model N | --slow N | --batch | --selfcheck LO HI | --thrtable | --shrink LO HI\n"); return 2; }
    emit(strtoull(argv[1], NULL, 10), 0, 0);
    return 0;
}

/* /workspace/spec/gencounts.c -- emit the sweep count list (sorted, unique) */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
typedef unsigned long long u64;

static u64 v[1<<16]; static size_t n = 0;
static void add(long long x) { if (x < 0) return; v[n++] = (u64)x; }
static int cmp(const void*a,const void*b){u64 x=*(const u64*)a,y=*(const u64*)b;return x<y?-1:(x>y?1:0);}

static u64 thr(int k) {           /* (size_t)((float)(1<<k) * 0.9f) */
    float bc = (float)((u64)1 << k);
    return (u64)(bc * 0.9f);
}

int main(int argc, char** argv) {
    u64 cap = (argc>1)? strtoull(argv[1],NULL,10) : 20000000ULL;   /* max count to emit */

    /* 1. every count 0..4200 */
    for (long long i = 0; i <= 4200; i++) add(i);

    /* 2. powers of two -1,+0,+1 up to 2^24 */
    for (int k = 0; k <= 24; k++) { long long p = 1LL<<k; add(p-1); add(p); add(p+1); }

    /* 3. growth boundaries: thr(k)-1, thr(k), thr(k)+1, thr(k)+2 for every bucket_count 2^k */
    for (int k = 1; k <= 24; k++) { long long t = (long long)thr(k); add(t-1); add(t); add(t+1); add(t+2); }

    /* 4. rehash boundaries: counts where round_up_pow2(2*size) flips, i.e. size = 2^j, 2^j+-1 */
    for (int k = 1; k <= 24; k++) { long long p = 1LL<<k; add(p/2-1); add(p/2); add(p/2+1); }

    /* 5. explicit interesting values */
    long long extra[] = {10000,20000,50000,65535,65536,65537,100000,123456,262143,262144,
                         500000,999999,1000000,1000001,1048575,1048576,1048577,
                         1887436,1887437,2000000,3774873,3774874,4194303,4194304,4194305,
                         7549747,7549748,8388607,8388608,8388609,10000000,15099494,15099495,16777215,16777216};
    for (size_t i = 0; i < sizeof extra/sizeof extra[0]; i++) add(extra[i]);

    qsort(v, n, sizeof v[0], cmp);
    u64 prev = (u64)-1;
    for (size_t i = 0; i < n; i++) {
        if (v[i] == prev) continue;
        if (v[i] > cap) break;
        prev = v[i];
        printf("%llu\n", v[i]);
    }
    return 0;
}

