/* find counts where f32 vs f64 division changes the printed %g, for lf1 and lf2 */
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <string.h>
typedef unsigned long long u64;
static u64 rup(u64 v){ if(!v) return 0; u64 p=1; while(p<v) p<<=1; return p; }
static u64 thr(u64 bc){ return (u64)((float)bc*0.9f); }
static u64 bcof(u64 c){ if(!c) return 0; u64 bc=0,t=thr(0); for(;;){ bc=bc?bc*2:2; t=thr(bc); if(c<=t) return bc; } }
int main(void){
  /* rehash want in double (corrected rule) */
  u64 lo=(u64)1<<23, hi=(u64)1<<27, nd1=0, nd2=0;
  for(u64 n=lo;n<=hi;n++){
    u64 bc1=bcof(n);
    u64 bc2=rup((u64)ceil((double)n/0.5));
    char a[64],b[64];
    float f1=(float)n/(float)bc1; double d1=(double)n/(double)bc1;
    snprintf(a,sizeof a,"%g",(double)f1); snprintf(b,sizeof b,"%g",d1);
    if(strcmp(a,b)){ if(nd1<12) printf("LF1 n=%llu bc=%llu f32=%s f64=%s\n",n,bc1,a,b); nd1++; }
    float f2=(float)n/(float)bc2; double d2=(double)n/(double)bc2;
    snprintf(a,sizeof a,"%g",(double)f2); snprintf(b,sizeof b,"%g",d2);
    if(strcmp(a,b)){ if(nd2<12) printf("LF2 n=%llu bc=%llu f32=%s f64=%s\n",n,bc2,a,b); nd2++; }
  }
  printf("range [2^23,2^27]: lf1 diffs=%llu lf2 diffs=%llu\n",nd1,nd2);
